(function(root){
const base=[{id:'flight',type:'Flight',title:'Nagpur → Mumbai',start:540,end:660,cost:5200,icon:'✈',detail:'6E 214 · NAG → BOM',deps:[]},{id:'transfer',type:'Transfer',title:'Airport → BKC',start:705,end:765,cost:900,icon:'↗',detail:'Reserved car · 60 min',deps:[{id:'flight',buffer:45}]},{id:'meeting',type:'Meeting',title:'Client strategy meeting',start:810,end:870,cost:0,icon:'◷',detail:'BKC, Mumbai · Fixed appointment',fixed:true,deps:[{id:'transfer',buffer:15}]},{id:'hotel',type:'Hotel',title:'Check in · The Westside',start:930,end:945,cost:4200,icon:'▥',detail:'Mumbai · One night',deps:[{id:'meeting',buffer:30}]},{id:'train',type:'Train',title:'Mumbai → Pune',start:1980,end:2190,cost:750,icon:'▤',detail:'Intercity Express · Day 2',deps:[{id:'hotel',buffer:60}]},{id:'event',type:'Event',title:'Product leadership summit',start:2250,end:2370,cost:1200,icon:'◇',detail:'Pune Convention Centre · Day 2',fixed:true,deps:[{id:'train',buffer:45}]}];
const clone=x=>JSON.parse(JSON.stringify(x));
function detect(items){let issues=[];for(const x of items){if(x.cancelled)issues.push({id:x.id,kind:'cancelled',message:x.title+' is cancelled'});for(const d of x.deps){let p=items.find(y=>y.id===d.id);if(p.cancelled)issues.push({id:x.id,kind:'dependency',message:x.title+' depends on a cancelled '+p.type.toLowerCase()});else if(p.end+d.buffer>x.start)issues.push({id:x.id,kind:'connection',gap:p.end+d.buffer-x.start,message:x.title+' needs '+(p.end+d.buffer-x.start)+' more minutes'});} }for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){let a=items[i],b=items[j];if(!a.cancelled&&!b.cancelled&&a.start<b.end&&b.start<a.end)issues.push({id:b.id,kind:'overlap',message:a.title+' overlaps '+b.title});}return issues;}
function propagate(items){let p=clone(items);for(let x of p){if(x.fixed||x.cancelled)continue;let earliest=Math.max(x.start,...x.deps.map(d=>p.find(y=>y.id===d.id).end+d.buffer));let duration=x.end-x.start;x.start=earliest;x.end=earliest+duration;}return p;}
function recover(items,budget){let options=[];let make=(id,title,description,extra,change)=>{let p=clone(items);change(p);p=propagate(p);let conflicts=detect(p),total=p.reduce((s,x)=>s+x.cost,0)+extra;options.push({id,title,description,extra,total,items:p,conflicts,feasible:conflicts.length===0&&total<=budget,score:conflicts.length*100000+Math.max(0,total-budget)*10+extra});};
make('car','Keep your flight, switch transfer','Use an available express car; retain the fixed meeting.',650,p=>{let t=p.find(x=>x.id==='transfer');t.end=t.start+30;});
make('flight','Take an earlier replacement flight','Simulated seat available on 6E 208; arrive at 10:45.',2400,p=>{let f=p[0];f.start=525;f.end=645;f.cancelled=false;f.detail='6E 208 · Alternative flight';});
make('meeting','Move the meeting to 15:30','Requires the client’s approval; retain your original transport.',0,p=>{let m=p.find(x=>x.id==='meeting');m.start=930;m.end=990;});
return options.sort((a,b)=>a.score-b.score);}
const api={base,clone,detect,propagate,recover};if(typeof module!=='undefined')module.exports=api;else root.JourneyEngine=api;
})(globalThis);
